var data = msg.payload;
data.received = new Date().toISOString();
flow.set('lastSensor', data);

var history = flow.get('history') || [];
history.push(data);
if (history.length > 50) history.shift();
flow.set('history', history);

var th = flow.get('threshold');
if (th === undefined || th === null) th = 35;
var alertMsg = null;
if (data.suhu > th) {
    alertMsg = {topic: 'iot/alert', payload: {pesan: 'Suhu melewati batas', suhu: data.suhu, batas: th, waktu: data.received}};
}
return [msg, alertMsg];

var key = msg.req.headers['x-api-key'];
if (key !== 'iot-kampus-2410010105') {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return msg;
}

var data = flow.get('lastSensor') || {suhu: null, kelembaban: null, timestamp: null};
var th = flow.get('threshold');
if (th === undefined || th === null) th = 35;
msg.payload = {
    status: 'success',
    data: data,
    threshold: th,
    alert: (data.suhu !== null && data.suhu > th),
    server_time: new Date().toISOString()
};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

var key = msg.req.headers['x-api-key'];
if (key !== 'iot-kampus-2410010105') {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return msg;
}

var history = flow.get('history') || [];
msg.payload = {
    status: 'success',
    count: history.length,
    data: history
};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

var key = msg.req.headers['x-api-key'];
if (key !== 'iot-kampus-2410010105') {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null];
}

var body = msg.payload;
if (!body.device || !body.action) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'device dan action wajib diisi'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null];
}

var mqttMsg = {payload: body, topic: 'iot/kontrol'};

msg.statusCode = 200;
msg.payload = {
    status: 'success',
    message: 'Perintah terkirim',
    sent: body
};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return [msg, mqttMsg];

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
return msg;

var key = msg.req.headers['x-api-key'];
if (key !== 'iot-kampus-2410010105') {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid'};
    return msg;
}

var b = msg.payload;
if (!b || b.max === undefined || isNaN(Number(b.max))) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'field max (angka) wajib diisi'};
    return msg;
}
flow.set('threshold', Number(b.max));
msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Batas suhu diperbarui', threshold: Number(b.max)};
return msg;
